import{_ as e,o as s,c as a,a3 as t}from"./chunks/framework.D2VFKYIt.js";const c=JSON.parse('{"title":"Existing tables and upgrades","description":"","frontmatter":{"order":50},"headers":[],"relativePath":"migrations/existing-tables.md","filePath":"migrations/existing-tables.md"}'),n={name:"migrations/existing-tables.md"};function r(o,i,l,h,d,p){return s(),a("div",null,[...i[0]||(i[0]=[t(`<h1 id="existing-tables-and-upgrades" tabindex="-1">Existing tables and upgrades <a class="header-anchor" href="#existing-tables-and-upgrades" aria-label="Permalink to &quot;Existing tables and upgrades&quot;">​</a></h1><h2 id="making-an-existing-table-temporal" tabindex="-1">Making an existing table temporal <a class="header-anchor" href="#making-an-existing-table-temporal" aria-label="Permalink to &quot;Making an existing table temporal&quot;">​</a></h2><p>When you call <code>IsTemporal()</code> on an entity whose table already has rows, the migration creates an <strong>empty</strong> history table. Hindsight does not seed it. Until a row changes for the first time, it has no version: <code>AsOf</code> returns nothing for it, and its history starts at that first change.</p><p>To give every existing row an initial version, seed the history table in the same migration, after it is created, with <code>migrationBuilder.Sql(…)</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> policies_history (id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, premium, effective_from, valid_from, valid_to, operation)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, premium, effective_from, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;infinity&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> policies;</span></span></code></pre></div><ul><li>List every versioned column, using your actual column names; leave out <a href="/hindsight-efcore/1.1/configuration/temporal-entities#excluding-properties">excluded</a> ones.</li><li><code>valid_from = now()</code> means &quot;known since the migration&quot;: <code>AsOf</code> before that instant still returns nothing, which is the truth.</li><li><code>operation = 1</code> records it as an insert. The change-context columns stay <code>NULL</code>.</li></ul><h2 id="upgrading-hindsight" tabindex="-1">Upgrading Hindsight <a class="header-anchor" href="#upgrading-hindsight" aria-label="Permalink to &quot;Upgrading Hindsight&quot;">​</a></h2><p>Upgrading the package is normally a no-op for your schema: run <code>dotnet ef migrations add</code> and expect an empty migration. When a release needs something more, the <a href="/hindsight-efcore/1.1/reference/upgrading">upgrade guide</a> says so, version by version.</p><h3 id="backfilling-the-period-range-index" tabindex="-1">Backfilling the period-range index <a class="header-anchor" href="#backfilling-the-period-range-index" aria-label="Permalink to &quot;Backfilling the period-range index {#backfilling-the-period-range-index}&quot;">​</a></h3><p>Since 1.1, every new history table gets a GiST index on its period, <code>ix_&lt;history_table&gt;_period</code> (see <a href="/hindsight-efcore/1.1/migrations/generated-schema#indexes">What a migration creates</a>). History tables created by 1.0 do not have it, and upgrading does not add it: the index is created only next to the history table&#39;s <code>CREATE TABLE</code>, so for existing tables <code>dotnet ef migrations add</code> scaffolds nothing.</p><p>Without it, a point-in-time query that is not also filtered by the entity&#39;s key scans the whole history table. Add it yourself, in a hand-written migration or directly:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CONCURRENTLY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ix_policies_history_period</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> policies_history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gist (tstzrange(valid_from, valid_to));</span></span></code></pre></div><ul><li>Use <code>CONCURRENTLY</code>. A plain <code>CREATE INDEX</code> blocks writes to the history table, and so every write to the main table under the trigger writer, for as long as the build takes. <code>CONCURRENTLY</code> cannot run inside a transaction, so run it outside a migration transaction.</li><li>Substitute your history table&#39;s name, and your period column names if you changed them with <code>HasPeriodStart</code> / <code>HasPeriodEnd</code>.</li><li>Keep the name <code>ix_&lt;history_table&gt;_period</code>, so your schema matches what a freshly created table gets.</li></ul>`,13)])])}const k=e(n,[["render",r]]);export{c as __pageData,k as default};
